#!/usr/bin/env python3
"""
Round 116b (culprits), 29 September 2026. Needs round 115b.

Glow orbs back, the drug underworld countries teal to cobalt, police
stations, courts and prisons filed under Law enforcement and Courts and
corrections too, and a row of gangs inside law enforcement worldwide.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

DIFF = ''
NOTE = '## Round 116b (29 September)\n\nNeeds round 115b. Tiles patch round116b_tiles.py beside it. No app.js?v= bump.\n\n- Points: the glow orbs are back (owner: "return back to the glow orb look"),\n  undoing 112b\'s solid dots: addHud adds haze, core and soft layers to every\n  point layer again, dots soft-edged and unseen wider out; legibleCircle\'s\n  light rim (POINT_RIM rgba(242,238,230,0.85), width 1). POINT_ZOOM sizing\n  kept. smallLayerDots (geojson rows of 500 points or fewer) also sets\n  circle-opacity 0.9 on a glowing layer, so few-point rows stay findable wide\n  out (the reason 112b gave for the solid dots).\n- capture_map (Drug underworld): countries shaded teal to cobalt in five steps\n  in place of the page\'s greys (cfg.colouringColours, cfg.colouringEdge\n  #08203F; sitemapColourings keeps edge; applySitemapColouring uses it).\n- bld_police (Law enforcement), bld_courts and bld_prisons (Courts and\n  corrections): the Buildings row\'s own files for one kind each\n  (cfg.onlyKinds in addBuildingTypesLayer: one colour, no list of kinds,\n  counts in the state line). Buildings keeps every kind.\n- gang_infiltration (Law enforcement): 24 documented cases in 15 countries\n  (tiles lawenforcement/gang_infiltration.geojson, compiled by hand from the\n  sources each box quotes; groupColours by "A crime group working through\n  police or officials" / "Officers running a gang or crime ring of their own";\n  status field says how far each was proven).\n- Holidays: holidays/culprits.geojson on tiles main has the 12 corporatizers\n  (no VFW) since 114b; the live copy still showed the 103b file, so the\n  tiles Pages deploy had not caught up.\n- Tiles fertility_policy.py: a failed build (found false) retries daily, not\n  only Mondays. The fixed script had not run since 111b.\n\n'
HEAD = "## Round 116b (29 September)"


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round116b: run from the culprits repository root")
    text = (root / "HANDOFF.md").read_text(encoding="utf-8")
    if "## Round 115b" not in text:
        sys.exit("round116b: round 115b must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", "--binary", path, check=False).returncode == 0:
        print("round116b: already applied")
    else:
        r = git("apply", "--3way", "--binary", path, check=False)
        if r.returncode != 0:
            sys.exit("round116b: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round116b: applied")
    h = root / "HANDOFF.md"
    text = h.read_text(encoding="utf-8")
    if HEAD not in text:
        at = text.index("## Round 115b")
        h.write_text(text[:at] + NOTE + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
